mapper.select:
SELECT pan.*, fatherDashboard.id AS parent_id, fatherDashboard.NAME AS parent_name, IFNULL( chart.chartNum, 0 ) AS chart_num , IFNULL( sta.starred, 0 ) AS starred, pan.var_type as varType FROM visual_dashboard pan LEFT JOIN visual_dashboard fatherDashboard ON pan.pid = fatherDashboard.id LEFT JOIN ( SELECT dashboard_id, count( 1 ) AS chartNum FROM visual_chart GROUP BY dashboard_id ) chart ON pan.id = chart.dashboard_id LEFT JOIN ( SELECT IF(COUNT(1) > 0, 1, 0) AS starred,tid FROM sys_user_starred WHERE TYPE = "dashboard" AND uid = #{params.currentLoginUserID} GROUP BY tid) sta ON pan.id = sta.tid
and pan.id in
#{id}
and pan.type=#{params.type}
AND locate(#{params.name} , pan.name)
and pan.create_by=#{params.createBy}
and pan.pid=#{params.pid}
and pan.link=#{params.link}
and pan.var_type=#{params.varType}
AND
starred = #{params.starred}
starred IS NULL
ORDER BY pan.id
ORDER BY pan.weight,pan.id

update.foreach:
UPDATE visual_dashboard

    weight = #{dashboard.weight},
    pid = #{dashboard.pid}

WHERE
id = #{dashboard.id}
